import Link from "next/link";
import { B_PATH, LOCKUP, PLAY_PATH, WORDMARK_PATH } from "@/components/brand-paths";

/*
 * Brightframe brand marks. Geometry and the outlined wordmark are generated by
 * scripts/brand/build-logo.mjs (also writes the standalone SVGs in /public/brand).
 *   <BrandMark>  the geometric B with its play triangle
 *   <Logo>       horizontal lockup (mark + "Brightframe"), as one SVG so it scales as a unit
 *   <AppIcon>    the square app icon
 * tone: "color" (forest + apricot, for light grounds), "dark" (ivory + apricot, for forest/dark grounds),
 *       "mono" (one colour = currentColor, play triangle knocked out).
 */
type Tone = "color" | "dark" | "mono";
const FILL: Record<Exclude<Tone, "mono">, { b: string; play: string; word: string }> = {
  color: { b: "var(--forest)", play: "var(--apricot)", word: "var(--forest)" },
  dark: { b: "var(--ivory)", play: "var(--apricot)", word: "var(--ivory)" },
};

function Play({ fill }: { fill: string }) {
  return <path d={PLAY_PATH} fill={fill} stroke={fill} strokeWidth={7} strokeLinejoin="round" />;
}

function MarkShapes({ tone, maskId }: { tone: Tone; maskId: string }) {
  if (tone === "mono") {
    return (
      <>
        <defs>
          <mask id={maskId} maskUnits="userSpaceOnUse" x="0" y="0" width="120" height="120">
            <rect width="120" height="120" fill="#fff" />
            <Play fill="#000" />
          </mask>
        </defs>
        <path d={B_PATH} fill="currentColor" mask={`url(#${maskId})`} />
      </>
    );
  }
  return (
    <>
      <path d={B_PATH} fill={FILL[tone].b} />
      <Play fill={FILL[tone].play} />
    </>
  );
}

export function BrandMark({ size = 28, tone = "color", className = "", title }: { size?: number; tone?: Tone; className?: string; title?: string }) {
  const id = `bfm-${tone}-${size}`;
  return (
    <svg viewBox="6 2 90 108" height={size} width={(size * 90) / 108} className={className} role={title ? "img" : undefined} aria-hidden={title ? undefined : true} aria-label={title}>
      <MarkShapes tone={tone} maskId={id} />
    </svg>
  );
}

export function Logo({ height = 28, tone = "color", className = "" }: { height?: number; tone?: Tone; className?: string }) {
  const id = `bfl-${tone}-${height}`;
  const word = tone === "mono" ? "currentColor" : FILL[tone].word;
  return (
    <svg viewBox={`0 0 ${LOCKUP.W} ${LOCKUP.H}`} height={height} width={(height * LOCKUP.W) / LOCKUP.H} className={className} role="img" aria-label="Brightframe">
      <g transform={LOCKUP.markT}><MarkShapes tone={tone} maskId={id} /></g>
      <g transform={LOCKUP.wordT}><path d={WORDMARK_PATH} fill={word} /></g>
    </svg>
  );
}

export function AppIcon({ size = 64, className = "" }: { size?: number; className?: string }) {
  return (
    <svg viewBox="0 0 1024 1024" width={size} height={size} className={className} aria-hidden>
      <rect width="1024" height="1024" rx="228" fill="var(--forest)" />
      <g transform="translate(226.4 198.4) scale(5.6)"><MarkShapes tone="dark" maskId="bfi" /></g>
    </svg>
  );
}

/** The logo as a home link. Kept under its old name so existing pages pick up the new brand. */
export function Wordmark({ href = "/", size = 28, light = false }: { href?: string; size?: number; light?: boolean }) {
  return (
    <Link href={href} className="inline-flex items-center rounded-md" aria-label="Brightframe home">
      <Logo height={size} tone={light ? "dark" : "color"} />
    </Link>
  );
}
